using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Scene VMAD phase fragments: after the flag byte, xEdit (wbDefinitionsSF1 'Phase Fragment') has the UInt32 Phase
// Index and then one unknown byte. Mutagen read the index as one byte and the next 4 bytes as a UInt32, so the
// unknown came out as 0x01000000 (the 6 bytes are always flag, index, 00 00 00, 01 in Starfield.esm).
// SPMV is xEdit's empty Phase Visibility Marker (5 in Starfield.esm, all 0 bytes).
// Each test reads a whole scene from Starfield.esm with both readers and writes it back byte for byte.
public class ScenePhaseFragmentTests
{
    private static IEnumerable<ISceneGetter> Read(string hex)
        => ReadBoth<ISceneGetter>(Record("SCEN", Hex(hex)), f => Scene.CreateFromBinary(f), (s, p) => SceneBinaryOverlay.SceneFactory(s, p));

    private static void WritesBack(ISceneGetter scen, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => scen.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // SE_KMK01GoodbyeScene (05BB5C:Starfield.esm)
    private const string Goodbye = "";

    // COM_Quest_Andreja_Q01_Stage330_Andreja (0F7904:Starfield.esm)
    private const string Andreja = "";

    [Fact]
    public void PhaseFragment_IndexIsUInt32()
    {
        foreach (var scen in Read(Goodbye))
        {
            var frags = scen.VirtualMachineAdapter.ShouldNotBeNull().ScriptFragments.ShouldNotBeNull().PhaseFragments;
            frags.ShouldNotBeEmpty();
            foreach (var frag in frags)
            {
                frag.Unknown.ShouldBe((byte)1);
            }
            frags.Single(f => f.FragmentName == "Fragment_Phase_02_End").Index.ShouldBe(1u);
            WritesBack(scen, Goodbye);
        }
    }

    [Fact]
    public void Phase_VisibilityMarker()
    {
        foreach (var scen in Read(Andreja))
        {
            scen.Phases.Count(p => p.PhaseVisibilityMarker).ShouldBe(1);
            WritesBack(scen, Andreja);
        }
    }
}
